 static void Edit(string p,Action<GameObject> action){var g=PrefabUtility.LoadPrefabContents(p);try{action(g);PrefabUtility.SaveAsPrefabAsset(g,p);}finally{PrefabUtility.UnloadPrefabContents(g);}}
