 static void Slice(){AssetDatabase.ImportAsset(Sheet,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(Sheet);ti.textureType=TextureImporterType.Sprite;ti.spriteImportMode=SpriteImportMode.Multiple;ti.alphaIsTransparency=true;ti.mipmapEnabled=false;ti.npotScale=TextureImporterNPOTScale.None;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();var factory=new SpriteDataProviderFactories();factory.Init();var dp=factory.GetSpriteEditorDataProviderFromObject(ti);dp.InitSpriteEditorDataProvider();var cap=dp.GetDataProvider<ISpriteFrameEditCapability>();if(cap==null)throw new Exception("No sprite capabilities");foreach(var c in new[]{EEditCapability.CreateAndDeleteSprite,EEditCapability.EditSpriteName,EEditCapability.EditSpriteRect,EEditCapability.EditBorder,EEditCapability.EditPivot})if(!cap.GetEditCapability().HasCapability(c))throw new Exception("Unsupported sprite operation "+c);
